import os, json, sys
sys.path.append('storage/shared/atlas/tools')
import ci_validate

def exists(p): return os.path.exists(p)
def load_idx(p):
    try:
        with open(p,'r',encoding='utf-8') as f: return json.load(f)
    except Exception:
        return {"entries": []}
def norm(ents):
    out=[]
    for e in ents:
        if isinstance(e, dict) and "entry_path" in e: out.append({"entry_path": e["entry_path"]})
        elif isinstance(e, dict) and "path" in e:     out.append({"entry_path": e["path"]})
        elif isinstance(e, str):                      out.append({"entry_path": e})
    return out
def save_idx(p, ents):
    with open(p,'w',encoding='utf-8') as f: json.dump({"entries": ents}, f, ensure_ascii=False, indent=2)

curated = 'storage/shared/atlas/edges/index.json'
ents = norm(load_idx(curated).get("entries", []))
before = set(e["entry_path"] for e in ents)
updates = []

logos_entry = 'storage/shared/atlas/edges/logos/verification_cauchy_densified_200_s5/entry.json'
aether_entry = 'storage/shared/atlas/edges/aether/renewal_hybrid_psilo/entry.json'
for e in [logos_entry, aether_entry]:
    if exists(e) and e not in before:
        ents.append({"entry_path": e}); updates.append({"added": e})

if updates:
    ents = sorted(ents, key=lambda x: x["entry_path"])
    save_idx(curated, ents)

out = ci_validate.run()
print(json.dumps({"status":"ok","updates": updates, "entries_found": out.get("entries_found"), "ok": out.get("ok"), "with_errors": out.get("with_errors")}))
